{
  "title": "Al-Faris Digital Services Privacy and User Agreement",
  "planted": [
    {
      "slot": "p1",
      "text": "Al-Faris Digital Services reserves the right to utilize all collected information for any business purpose deemed appropriate by the management, including unforeseen future initiatives and operational adaptations not explicitly detailed herein."
    },
    {
      "slot": "p2",
      "text": "Users acknowledge that review of internal system records or modification of archived profile configurations remains strictly restricted to administrative discretion, and requests for profile purging or record adjustments are subject to administrative review without guarantee of execution."
    },
    {
      "slot": "p3",
      "text": "All user records and transaction histories are retained indefinitely within our archival databases following account deactivation to support long-term trend analysis and historical continuity."
    },
    {
      "slot": "p4",
      "text": "Certain operational activities may be executed without explicit user authorization where such processing is strictly necessary to fulfill pre-existing contractual obligations or administrative duties, and users retain the ability to rescind their authorization for discretionary processing at any time through account settings."
    }
  ],
  "neutral": [
    "All service fees are billed in the local currency and must be settled in full prior to the activation of any recurring subscription tier or digital product delivery.",
    "Users may terminate their account agreement at any time by submitting a formal closure request through the designated support portal, subject to the settlement of any outstanding financial balances.",
    "Al-Faris Digital Services shall not be held liable for any indirect, incidental, or consequential damages arising from service interruptions caused by third-party telecommunication providers or unforeseen technical maintenance.",
    "This agreement shall be governed by and construed in accordance with the substantive laws applicable within the jurisdiction of the company's primary headquarters, excluding conflict of law principles.",
    "All trademarks, logos, interface designs, and proprietary software code displayed on the platform remain the exclusive intellectual property of Al-Faris Digital Services and may not be reproduced without prior written authorization.",
    "Official notices directed to the company must be transmitted via certified electronic mail to the designated corporate address listed on our contact page, and shall be deemed received upon successful delivery confirmation."
  ]
